import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；route(0,True)=weekday、route(5,True)=weekend 為已確認例子。

    def test_confirmed_examples(self):
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_boundaries(self):
        # day 0..4 -> weekday；抓 >=4 / >=6 之類邊界錯誤
        for day in (0, 1, 2, 3, 4):
            self.assertEqual(route(day, True), "weekday", day)

    def test_weekend_boundaries(self):
        for day in (5, 6):
            self.assertEqual(route(day, True), "weekend", day)

    def test_paused_when_disabled_for_every_valid_day(self):
        # 抓忽略 enabled 的退化
        for day in range(7):
            self.assertEqual(route(day, False), "paused", day)

    def test_out_of_range_rejected(self):
        # -1 與 7 剛好在邊界外；enabled 兩種值都要先驗 day
        for day in (-1, 7, 100):
            for enabled in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(day, enabled)

    def test_non_int_string_rejected(self):
        for day in ("0", "5", "abc"):
            for enabled in (True, False):
                with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                    route(day, enabled)
